// Project photo albums for the /gallery page.
// Images live in /public/images/gallery/<slug>/ (full size) and
// /public/images/gallery/<slug>/thumbs/ (small previews). To add photos to a
// project, drop them in that folder and add the path to its `media` list.

export type GalleryCategoryKey =
  | "partitions"
  | "showers"
  | "facades"
  | "retail"
  | "doors"
  | "interiors"
  | "railings"
  | "products";

export type GalleryMedia = {
  type: "image" | "video";
  src: string;
  /** Small preview used in the thumbnail strip (images only). */
  thumb?: string;
};

export type GalleryProject = {
  slug: string;
  title: string;
  location: string;
  category: GalleryCategoryKey;
  /** Thumbnail shown on the project card. */
  cover: string;
  photoCount: number;
  media: GalleryMedia[];
};

